    }
  },
  "RENDERING_STYLE": {
    "LOOK": "photorealistic studio portrait with subtle fantasy features",
    "SKIN": "keep natural pores and freckles, no plastic skin, no over-smoothing",
    "COLOR_GRADING": "clean neutral, high-key studio tones"
  },
